{"path": "dominoes.py", "content": "def can_chain(dominoes):
    """Return an ordered, valid closed chain of the dominoes, or None."""
    dominoes = list(dominoes)
    if not dominoes:
        return []

    def extend(chain, remaining):
        if not remaining:
            return chain if chain[0][0] == chain[-1][1] else None
        end = chain[-1][1]
        seen = set()
        for i, (a, b) in enumerate(remaining):
            if (a, b) in seen:
                continue
            seen.add((a, b))
            rest = remaining[:i] + remaining[i + 1:]
            for stone in ((a, b), (b, a)):
                if stone[0] == end:
                    result = extend(chain + [stone], rest)
                    if result:
                        return result
        return None

    first = dominoes[0]
    rest = dominoes[1:]
    return extend([tuple(first)], [tuple(d) for d in rest])
